//
// core/tile/compat (the port of DroneDB 2.4.1's tile maths) against gdal2tiles.py's
// GlobalMercator and geo_query (GDAL 3.13.3), the code DroneDB's was copied from. The reference
// values are generated by data/gen_parity.py (libddb exports no tile maths to call: see there).
// Equal bit for bit where the two implementations do the same operations; the known, deliberate
// differences are asserted as such.

#include <gtest/gtest.h>

#include <algorithm>
#include <bit>
#include <cmath>
#include <cstdint>
#include <limits>

#include "core/tile/compat.h"
#include "core/tile/web_mercator.h"

namespace {

struct ResolutionCase {
    int tileSize, z;
    double res;
};
struct BoundsCase {
    int tileSize, z, tx, ty;
    double minx, miny, maxx, maxy;
};
struct MetersToTileCase {
    int tileSize, z;
    double mx, my;
    int tx, ty;
};
struct ZoomCase {
    int tileSize;
    double pixelSize;
    int zoom;
};
struct LatLonCase {
    double lat, lon, mx, my, backLat, backLon;
};
struct GeoQueryCase {
    double gt[6];
    int xsize, ysize, tileSize, z, tx, ty;
    double ulx, uly, lrx, lry;
    int r[4], w[4];
    int clamped;  // gdal2tiles clamped the read size to 1 px (DroneDB does not)
};
struct MinMaxCase {
    int tileSize;
    double gt[6];
    int xsize, ysize, z, tminz, tmaxz;
    int range[4];  // gdal2tiles: columns AND rows cropped to the world
};

#include "data/gdal2tiles_parity.inc"

using ddbt::tile::compat::GlobalMercator;
namespace compat = ddbt::tile::compat;

uint64_t Bits(double v) { return std::bit_cast<uint64_t>(v); }

#define EXPECT_SAME_BITS(a, b) EXPECT_EQ(Bits(a), Bits(b)) << #a " = " << (a) << ", " #b " = " << (b)

TEST(TileCompatParity, Resolution) {
    for (const auto& c : kResolutionCases) {
        const GlobalMercator m(c.tileSize);
        EXPECT_SAME_BITS(m.resolution(c.z), c.res) << c.tileSize << " z" << c.z;
        const ddbt::tile::WebMercatorQuad q(c.tileSize);
        EXPECT_SAME_BITS(q.Resolution(c.z), c.res);
    }
}

TEST(TileCompatParity, TileBounds) {
    for (const auto& c : kBoundsCases) {
        const GlobalMercator m(c.tileSize);
        const auto b = m.tileBounds(c.tx, c.ty, c.z);
        EXPECT_SAME_BITS(b.min.x, c.minx);
        EXPECT_SAME_BITS(b.min.y, c.miny);
        EXPECT_SAME_BITS(b.max.x, c.maxx);
        EXPECT_SAME_BITS(b.max.y, c.maxy);
        // The clean API gives the same metres (TMS row here).
        const ddbt::tile::WebMercatorQuad q(c.tileSize);
        const auto cb = q.TileBounds(c.z, c.tx, c.ty, ddbt::tile::Scheme::TMS);
        EXPECT_SAME_BITS(cb.minX, c.minx);
        EXPECT_SAME_BITS(cb.minY, c.miny);
        EXPECT_SAME_BITS(cb.maxX, c.maxx);
        EXPECT_SAME_BITS(cb.maxY, c.maxy);
    }
}

TEST(TileCompatParity, MetersToTile) {
    for (const auto& c : kMetersToTileCases) {
        const GlobalMercator m(c.tileSize);
        const auto t = m.metersToTile(c.mx, c.my, c.z);
        EXPECT_EQ(t.x, c.tx) << c.mx << " z" << c.z;
        EXPECT_EQ(t.y, c.ty) << c.my << " z" << c.z;
    }
}

TEST(TileCompatParity, ZoomForPixelSize) {
    // gdal2tiles: max(0, i - 1) over 32 levels; DroneDB: i - 1 over 99 levels.
    for (const auto& c : kZoomCases) {
        const GlobalMercator m(c.tileSize);
        const int z = m.zoomForPixelSize(c.pixelSize);
        if (z < 0) {
            EXPECT_EQ(c.zoom, 0);
            EXPECT_GT(c.pixelSize, m.resolution(0));
        } else {
            EXPECT_EQ(z, c.zoom) << c.pixelSize;
        }
    }
}

TEST(TileCompatParity, LatLonMeters) {
    for (const auto& c : kLatLonCases) {
        EXPECT_SAME_BITS(ddbt::tile::LonToMeters(c.lon), c.mx);
        EXPECT_SAME_BITS(ddbt::tile::LatToMeters(c.lat), c.my);
        EXPECT_SAME_BITS(ddbt::tile::MetersToLon(c.mx), c.backLon);
        EXPECT_SAME_BITS(ddbt::tile::MetersToLat(c.my), c.backLat);
    }
}

TEST(TileCompatParity, GeoQuery) {
    int compared = 0, clamped = 0;
    for (const auto& c : kGeoQueryCases) {
        const auto q = compat::GeoQuery(c.gt, c.xsize, c.ysize, c.ulx, c.uly, c.lrx, c.lry, c.tileSize);
        ASSERT_TRUE(q.has_value());
        // The query box is the tile's bounds, as GDALTiler::tileWindow passes them.
        const GlobalMercator m(c.tileSize);
        const auto b = m.tileBounds(c.tx, c.ty, c.z);
        ASSERT_EQ(Bits(b.min.x), Bits(c.ulx));
        ASSERT_EQ(Bits(b.max.y), Bits(c.uly));
        if (c.clamped) {
            // gdal2tiles reads at least one pixel; the baseline computes a 0 px read, and
            // tileWindow then emits a transparent tile.
            ++clamped;
            EXPECT_TRUE(q->r.xsize <= 0 || q->r.ysize <= 0);
            continue;
        }
        ++compared;
        const int r[4] = {q->r.x, q->r.y, q->r.xsize, q->r.ysize};
        const int w[4] = {q->w.x, q->w.y, q->w.xsize, q->w.ysize};
        for (int i = 0; i < 4; ++i) {
            EXPECT_EQ(r[i], c.r[i]) << "r[" << i << "] z" << c.z << " " << c.tx << "," << c.ty;
            EXPECT_EQ(w[i], c.w[i]) << "w[" << i << "] z" << c.z << " " << c.tx << "," << c.ty;
        }
    }
    EXPECT_GT(compared, 300);
    EXPECT_GT(clamped, 0);
}

TEST(TileCompatParity, ZoomAndTileRanges) {
    for (const auto& c : kMinMaxCases) {
        const compat::RasterTiling t(c.tileSize, c.gt, c.xsize, c.ysize);
        // Square pixels: the baseline's gt[1] for the south bound equals gdal2tiles' -gt[5].
        ASSERT_EQ(c.gt[1], -c.gt[5]);
        EXPECT_EQ(t.zooms.min, c.tminz);
        EXPECT_EQ(t.zooms.max, c.tmaxz);
        const auto b = compat::MinMaxCoordsForZ(t.mercator, t.bounds.oMinX, t.bounds.oMinY, t.bounds.oMaxX,
                                                t.bounds.oMaxY, c.z);
        EXPECT_EQ(b.min.x, c.range[0]);
        EXPECT_EQ(b.max.x, c.range[2]);
        // gdal2tiles crops rows too; the baseline does not.
        EXPECT_EQ(std::max(0, b.min.y), c.range[1]);
        EXPECT_EQ(std::min((1 << c.z) - 1, b.max.y), c.range[3]);
    }
}

}  // namespace
